// Lấy SVG cho một từ: ưu tiên khóa theo chủ đề, sau đó theo từ.
export function iconFor(word) {
  if (!word) return null;
  return ICONS[`${word.topic}:${word.ko}`] || ICONS[word.ko] || null;
}
export const hasIcon = w => !!iconFor(w);
export const ICON_COUNT = Object.keys(ICONS).length;
